# 동영상: 잘라서 보내기 · 음악으로 저장
#  - 새 화면 파일(video_trim_screen.dart)도 이 파일이 직접 만들어요
# 실행: python apply_video_trim.py   (mp3_player_new 폴더에서)
import os, sys

SCREEN = os.path.join('lib', 'screens', 'video_screen.dart')
NEW_FILE = os.path.join('lib', 'screens', 'video_trim_screen.dart')
