NEW_DART = "import 'dart:io';\nimport 'package:flutter/material.dart';\nimport 'package:flutter/services.dart';\nimport 'package:provider/provider.dart';\nimport 'package:share_plus/share_plus.dart';\nimport 'package:video_player/video_player.dart';\nimport '../models/video.dart';\nimport '../l10n/app_localizations.dart';\nimport '../providers/music_provider.dart';\nimport '../providers/theme_provider.dart';\nimport '../providers/video_provider.dart';\nimport '../widgets/action_feedback.dart';\nimport '../widgets/paran_dialog.dart';\nimport '../widgets/paran_toast.dart';\n\nconst _media = MethodChannel('kr.ssing.catsong/media');\nvoid _vib() => _media.invokeMethod('vibrate');\n\n/// 동영상 소리만 뽑아서 음악으로 저장 (Music/Paransori · m4a) — 저장됐으면 true\nFuture<bool> saveVideoAudio(BuildContext context, Video video, int startMs, int endMs, {bool whole = false}) async {\n  try {\n    final saved = await _media.invokeMethod<String>('extractAudio', {\n      'path': video.uri,\n      'startMs': startMs,\n      'endMs': endMs,\n      'outBase': whole ? video.title : '${video.title}_자름',\n    });\n    if (!context.mounted) return saved != null;\n    if (saved == null) {\n      showParanToast(context, '음악으로 저장하지 못했어요', error: true);\n      return false;\n    }\n    context.read<MusicProvider>().loadSongs(); // 음악 목록에 바로 보이게\n    showActionFeedback(context,\n        type: ActionFeedbackType.saved, message: '음악으로 저장했어요', icon: Icons.music_note_rounded);\n    return true;\n  } catch (e) {\n    if (context.mounted) showParanToast(context, '음악으로 저장하지 못했어요', error: true);\n    return false;\n  }\n}\n\n/// 음악으로 저장: 전체 저장 / 구간 골라서 저장 (앱 공통 고르는 창)\nFuture<void> showSaveAudioSheet(BuildContext context, Video video) async {\n  final isDark = context.read<ThemeProvider>().isDarkMode;\n  final sub = isDark ? const Color(0xFFA29A8B) : const Color(0xFF8A8378);\n  final pick = await showParanSheet<String>(\n    context,\n    title: '음악으로 저장',\n    builder: (ctx, setSheet) => Column(\n      crossAxisAlignment: CrossAxisAlignment.stretch,\n      children: [\n        Padding(\n          padding: const EdgeInsets.fromLTRB(4, 0, 4, 12),\n          child: Text('영상의 소리만 뽑아서 음악 목록에 넣어요',\n              style: TextStyle(color: sub, fontSize: 13, height: 1.4)),\n        ),\n        ParanCard(children: [\n          ParanRow(\n            icon: Icons.music_note_rounded,\n            title: '전체 저장',\n            trailingText: video.durationFormatted,\n            onTap: () => Navigator.pop(ctx, 'all'),\n          ),\n          ParanRow(\n            icon: Icons.content_cut_rounded,\n            title: '구간 골라서 저장',\n            onTap: () => Navigator.pop(ctx, 'pick'),\n          ),\n        ]),\n      ],\n    ),\n  );\n  if (!context.mounted || pick == null) return;\n  if (pick == 'all') {\n    await saveVideoAudio(context, video, 0, video.duration, whole: true);\n  } else {\n    await Navigator.push(\n      context,\n      MaterialPageRoute(builder: (_) => VideoTrimScreen(video: video, audioOnly: true)),\n    );\n  }\n}\n\n/// 동영상 자르기 화면 (벨소리·녹음 자르기 화면과 같은 모양)\n/// audioOnly = false: 잘라서 보내기 / 저장만 · true: 고른 구간을 음악으로 저장\nclass VideoTrimScreen extends StatefulWidget {\n  final Video video;\n  final bool audioOnly;\n  const VideoTrimScreen({super.key, required this.video, this.audioOnly = false});\n\n  @override\n  State<VideoTrimScreen> createState() => _VideoTrimScreenState();\n}\n\nclass _VideoTrimScreenState extends State<VideoTrimScreen> {\n  late final VideoPlayerController _ctrl;\n  double _max = 1; // 영상 길이 (초)\n  double _start = 0;\n  double _end = 1;\n  bool _previewing = false;\n  bool _busy = false;\n\n  @override\n  void initState() {\n    super.initState();\n    _max = widget.video.duration > 1000 ? widget.video.duration / 1000 : 1;\n    _end = _max;\n    _ctrl = VideoPlayerController.file(File(widget.video.uri));\n    _ctrl.initialize().then((_) {\n      if (mounted) setState(() {});\n    });\n    _ctrl.addListener(_onTick);\n  }\n\n  // 미리 보기: 고른 끝에 닿으면 멈추기\n  void _onTick() {\n    if (!_previewing) return;\n    if (_ctrl.value.position.inMilliseconds >= (_end * 1000).toInt()) {\n      _ctrl.pause();\n      if (mounted) setState(() => _previewing = false);\n    }\n  }\n\n  @override\n  void dispose() {\n    _ctrl.removeListener(_onTick);\n    _ctrl.dispose();\n    super.dispose();\n  }\n\n  int get _startMs => (_start * 1000).toInt();\n  int get _endMs => _end >= _max ? widget.video.duration : (_end * 1000).toInt();\n\n  Future<void> _togglePreview() async {\n    if (!_ctrl.value.isInitialized) return;\n    _vib();\n    if (_previewing) {\n      await _ctrl.pause();\n      setState(() => _previewing = false);\n      return;\n    }\n    await _ctrl.seekTo(Duration(milliseconds: _startMs));\n    await _ctrl.play();\n    setState(() => _previewing = true);\n  }\n\n  Future<void> _stopPreview() async {\n    if (!_previewing) return;\n    await _ctrl.pause();\n    if (mounted) setState(() => _previewing = false);\n  }\n\n  // 잘라서 저장 (send = true면 저장 후 바로 공유 창)\n  Future<void> _cut({required bool send}) async {\n    await _stopPreview();\n    if (send && _end - _start > 600) {\n      final ok = await showParanConfirm(\n        context,\n        title: '긴 동영상이에요',\n        message: '10분이 넘는 영상은 카카오톡으로 안 보내질 수 있어요.\\n구글 드라이브나 메일로 보내면 잘 가요.',\n        confirmLabel: '보내기',\n      );\n      if (!ok || !mounted) return;\n    }\n    setState(() => _busy = true);\n    try {\n      final saved = await _media.invokeMethod<String>('trimVideo', {\n        'path': widget.video.uri,\n        'startMs': _startMs,\n        'endMs': _endMs,\n        'outBase': '${widget.video.title}_자름',\n      });\n      if (!mounted) return;\n      if (saved == null) {\n        showParanToast(context, '자르지 못했어요', error: true);\n        return;\n      }\n      context.read<VideoProvider>().loadVideos(quiet: true); // 동영상 목록에 바로 보이게\n      if (send) {\n        await Share.shareXFiles([XFile(saved)], text: widget.video.titleDisplay);\n      } else {\n        showActionFeedback(context,\n            type: ActionFeedbackType.saved, message: '잘라서 저장했어요', icon: Icons.content_cut_rounded);\n      }\n      if (mounted) Navigator.pop(context);\n    } catch (e) {\n      if (mounted) showParanToast(context, '자르지 못했어요', error: true);\n    } finally {\n      if (mounted) setState(() => _busy = false);\n    }\n  }\n\n  Future<void> _saveAudio() async {\n    await _stopPreview();\n    setState(() => _busy = true);\n    final ok = await saveVideoAudio(context, widget.video, _startMs, _endMs, whole: _start == 0 && _end >= _max);\n    if (!mounted) return;\n    setState(() => _busy = false);\n    if (ok) Navigator.pop(context);\n  }\n\n  String _fmt(double sec) {\n    final s = sec.round();\n    return '${s ~/ 60}:${(s % 60).toString().padLeft(2, '0')}';\n  }\n\n  String _len(double sec) {\n    final s = sec.round();\n    return s >= 60 ? '${s ~/ 60}분 ${s % 60}초' : '$s초';\n  }\n\n  @override\n  Widget build(BuildContext context) {\n    final isDark = context.watch<ThemeProvider>().isDarkMode;\n    // ── 벨소리·녹음 자르기 화면과 같은 모양 (베이지 바탕 · 흰 카드 · 먹색 큰 버튼) ──\n    final bg = isDark ? const Color(0xFF17140F) : const Color(0xFFF4EFE5);\n    final card = isDark ? const Color(0xFF26221C) : Colors.white;\n    final ink = isDark ? const Color(0xFFF3EFE7) : const Color(0xFF17140F);\n    final sub = isDark ? const Color(0xFFA29A8B) : const Color(0xFF8A8378);\n    final line = isDark ? const Color(0xFF3A342B) : const Color(0xFFE2DACB);\n    final point = context.watch<ThemeProvider>().primaryColor;\n    final ready = _ctrl.value.isInitialized;\n    final l = AppLocalizations.of(context)!;\n\n    Widget section(String text) => Padding(\n          padding: const EdgeInsets.fromLTRB(4, 14, 4, 8),\n          child: Text(text, style: TextStyle(color: sub, fontSize: 12, fontWeight: FontWeight.w600)),\n        );\n    Widget whiteCard(Widget child, {EdgeInsets padding = const EdgeInsets.all(14)}) => Container(\n          width: double.infinity,\n          padding: padding,\n          decoration: BoxDecoration(color: card, borderRadius: BorderRadius.circular(16)),\n          child: child,\n        );\n    Widget timeChip(String t) => Container(\n          padding: const EdgeInsets.symmetric(horizontal: 10, vertical: 5),\n          decoration:\n              BoxDecoration(color: point.withOpacity(isDark ? 0.18 : 0.08), borderRadius: BorderRadius.circular(12)),\n          child: Text(t, style: TextStyle(color: point, fontSize: 12.5, fontWeight: FontWeight.w700)),\n        );\n    final sliderTheme = SliderTheme.of(context).copyWith(\n      activeTrackColor: point,\n      inactiveTrackColor: line,\n      thumbColor: point,\n      overlayColor: point.withOpacity(0.1),\n      trackHeight: 3,\n    );\n    Widget rangeRow(String label, double value, ValueChanged<double> onChanged) => Row(\n          children: [\n            SizedBox(width: 40, child: Text(label, style: TextStyle(color: sub, fontSize: 13))),\n            Expanded(\n              child: SliderTheme(\n                data: sliderTheme,\n                child: Slider(\n                  value: value.clamp(0, _max).toDouble(),\n                  min: 0,\n                  max: _max,\n                  onChanged: _busy\n                      ? null\n                      : (v) {\n                          if (_previewing) {\n                            _ctrl.pause();\n                            _previewing = false;\n                          }\n                          onChanged(v);\n                        },\n                  // 손을 떼면 그 장면을 미리 보기에 보여주기\n                  onChangeEnd: (v) {\n                    if (ready) _ctrl.seekTo(Duration(milliseconds: (v * 1000).toInt()));\n                  },\n                ),\n              ),\n            ),\n            SizedBox(\n                width: 44,\n                child: Text(_fmt(value), textAlign: TextAlign.right, style: TextStyle(color: ink, fontSize: 13))),\n          ],\n        );\n\n    final mainStyle = ElevatedButton.styleFrom(\n      backgroundColor: ink,\n      foregroundColor: bg,\n      disabledBackgroundColor: ink.withOpacity(0.5),\n      disabledForegroundColor: bg,\n      elevation: 6,\n      shadowColor: Colors.black.withOpacity(0.25),\n      shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(14)),\n    );\n    final subStyle = OutlinedButton.styleFrom(\n      backgroundColor: card,\n      foregroundColor: ink,\n      side: BorderSide(color: line),\n      shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(14)),\n    );\n    Widget spinner() =>\n        SizedBox(width: 18, height: 18, child: CircularProgressIndicator(strokeWidth: 2, color: bg));\n\n    return Scaffold(\n      backgroundColor: bg,\n      appBar: AppBar(\n        backgroundColor: bg,\n        elevation: 0,\n        scrolledUnderElevation: 0,\n        titleSpacing: 0,\n        systemOverlayStyle: SystemUiOverlayStyle(\n          statusBarColor: Colors.transparent,\n          statusBarIconBrightness: isDark ? Brightness.light : Brightness.dark,\n          statusBarBrightness: isDark ? Brightness.dark : Brightness.light,\n          systemNavigationBarColor: bg,\n          systemNavigationBarIconBrightness: isDark ? Brightness.light : Brightness.dark,\n        ),\n        title: Text(widget.audioOnly ? '음악으로 저장' : '잘라서 보내기',\n            style: TextStyle(color: ink, fontSize: 17, fontWeight: FontWeight.w800, letterSpacing: -0.3)),\n        leading: IconButton(\n          onPressed: () {\n            _vib();\n            Navigator.pop(context);\n          },\n          icon: Icon(Icons.arrow_back_ios_new_rounded, color: ink, size: 20),\n        ),\n      ),\n      // 버튼은 맨 아래에 모아서 (벨소리 자르기와 같게)\n      bottomNavigationBar: SafeArea(\n        top: false,\n        child: Padding(\n          padding: const EdgeInsets.fromLTRB(16, 8, 16, 12),\n          child: Column(\n            mainAxisSize: MainAxisSize.min,\n            children: [\n              // 미리 보기 (흰 버튼)\n              SizedBox(\n                width: double.infinity,\n                height: 48,\n                child: OutlinedButton.icon(\n                  onPressed: ready && !_busy ? _togglePreview : null,\n                  style: subStyle,\n                  icon: Icon(_previewing ? Icons.stop_rounded : Icons.play_arrow_rounded, size: 22),\n                  label: Text(_previewing ? '멈추기' : (widget.audioOnly ? '미리 듣기' : '미리 보기'),\n                      style: const TextStyle(fontSize: 14.5, fontWeight: FontWeight.w600)),\n                ),\n              ),\n              const SizedBox(height: 8),\n              if (widget.audioOnly)\n                // 음악으로 저장 (먹색 큰 버튼)\n                SizedBox(\n                  width: double.infinity,\n                  height: 50,\n                  child: ElevatedButton.icon(\n                    onPressed: _busy ? null : _saveAudio,\n                    style: mainStyle,\n                    icon: _busy ? spinner() : const Icon(Icons.music_note_rounded, size: 20),\n                    label: const Text('음악으로 저장', style: TextStyle(fontSize: 15, fontWeight: FontWeight.w700)),\n                  ),\n                )\n              else\n                // 저장만 (흰 버튼) · 보내기 (먹색 큰 버튼)\n                Row(\n                  children: [\n                    Expanded(\n                      child: SizedBox(\n                        height: 50,\n                        child: OutlinedButton.icon(\n                          onPressed: _busy ? null : () => _cut(send: false),\n                          style: subStyle,\n                          icon: const Icon(Icons.save_alt_rounded, size: 20),\n                          label: const Text('저장만', style: TextStyle(fontSize: 15, fontWeight: FontWeight.w600)),\n                        ),\n                      ),\n                    ),\n                    const SizedBox(width: 8),\n                    Expanded(\n                      child: SizedBox(\n                        height: 50,\n                        child: ElevatedButton.icon(\n                          onPressed: _busy ? null : () => _cut(send: true),\n                          style: mainStyle,\n                          icon: _busy ? spinner() : const Icon(Icons.ios_share_rounded, size: 20),\n                          label: const Text('보내기', style: TextStyle(fontSize: 15, fontWeight: FontWeight.w700)),\n                        ),\n                      ),\n                    ),\n                  ],\n                ),\n            ],\n          ),\n        ),\n      ),\n      body: SingleChildScrollView(\n        padding: const EdgeInsets.fromLTRB(16, 4, 16, 16),\n        child: Column(\n          crossAxisAlignment: CrossAxisAlignment.start,\n          children: [\n            // 영상 미리 보기 (세로 영상도 화면을 다 덮지 않게 높이 고정)\n            GestureDetector(\n              onTap: ready && !_busy ? _togglePreview : null,\n              child: ClipRRect(\n                borderRadius: BorderRadius.circular(16),\n                child: Container(\n                  height: MediaQuery.of(context).size.height * 0.34,\n                  width: double.infinity,\n                  color: Colors.black,\n                  alignment: Alignment.center,\n                  child: ready\n                      ? Stack(\n                          alignment: Alignment.center,\n                          children: [\n                            AspectRatio(aspectRatio: _ctrl.value.aspectRatio, child: VideoPlayer(_ctrl)),\n                            if (!_previewing)\n                              Container(\n                                width: 52,\n                                height: 52,\n                                decoration: BoxDecoration(\n                                  color: Colors.black.withOpacity(0.45),\n                                  shape: BoxShape.circle,\n                                ),\n                                child: const Icon(Icons.play_arrow_rounded, color: Colors.white, size: 32),\n                              ),\n                          ],\n                        )\n                      : const SizedBox(\n                          width: 24,\n                          height: 24,\n                          child: CircularProgressIndicator(strokeWidth: 2, color: Colors.white54),\n                        ),\n                ),\n              ),\n            ),\n            Padding(\n              padding: const EdgeInsets.fromLTRB(4, 10, 4, 0),\n              child: Text(widget.video.titleDisplay,\n                  maxLines: 1,\n                  overflow: TextOverflow.ellipsis,\n                  style: TextStyle(color: ink, fontSize: 14.5, fontWeight: FontWeight.w700)),\n            ),\n            section(l.selectRange),\n            whiteCard(\n              Column(\n                children: [\n                  rangeRow(l.start, _start, (v) {\n                    if (v < _end - 1) setState(() => _start = v);\n                  }),\n                  rangeRow(l.end, _end, (v) {\n                    if (v > _start + 1) setState(() => _end = v);\n                  }),\n                  const SizedBox(height: 6),\n                  Row(\n                    mainAxisAlignment: MainAxisAlignment.spaceBetween,\n                    children: [\n                      timeChip(_fmt(_start)),\n                      Text(_len(_end - _start), style: TextStyle(color: sub, fontSize: 12.5)),\n                      timeChip(_fmt(_end)),\n                    ],\n                  ),\n                ],\n              ),\n              padding: const EdgeInsets.fromLTRB(10, 10, 14, 14),\n            ),\n            // 짧은 안내 (회색)\n            Padding(\n              padding: const EdgeInsets.fromLTRB(4, 12, 4, 0),\n              child: Text(\n                widget.audioOnly\n                    ? '고른 구간의 소리만 음악 목록에 저장해요 (Music/Paransori · M4A)'\n                    : '원본은 그대로 두고 잘라낸 영상을 새로 저장해요 (Movies/Paransori)\\n다시 압축하지 않아 화질 그대로예요. 시작이 1초쯤 앞당겨질 수 있어요',\n                style: TextStyle(color: sub, fontSize: 12, height: 1.5),\n              ),\n            ),\n          ],\n        ),\n      ),\n    );\n  }\n}\n"
SCREEN_EDITS = [('자르기 화면 불러오기', "import '../widgets/paran_toast.dart';\n", "import '../widgets/paran_toast.dart';\nimport 'video_trim_screen.dart';\n"), ('길게 누르기 창: 잘라서 보내기 · 음악으로 저장 (공유하기 아래)', "                      action(Icons.ios_share_rounded, '공유하기', ink, bg,\n                          isDarkMode ? const Color(0xFFCFC8BB) : const Color(0xFF5A5348),\n                          () => shareVideo(context, widget.video)),\n                      Divider(height: 1, thickness: 1, color: line),\n", "                      action(Icons.ios_share_rounded, '공유하기', ink, bg,\n                          isDarkMode ? const Color(0xFFCFC8BB) : const Color(0xFF5A5348),\n                          () => shareVideo(context, widget.video)),\n                      Divider(height: 1, thickness: 1, color: line),\n                      action(Icons.content_cut_rounded, '잘라서 보내기', ink, bg,\n                          isDarkMode ? const Color(0xFFCFC8BB) : const Color(0xFF5A5348),\n                          () => Navigator.push(\n                              context, MaterialPageRoute(builder: (_) => VideoTrimScreen(video: widget.video)))),\n                      Divider(height: 1, thickness: 1, color: line),\n                      action(Icons.music_note_rounded, '음악으로 저장', ink, bg,\n                          isDarkMode ? const Color(0xFFCFC8BB) : const Color(0xFF5A5348),\n                          () => showSaveAudioSheet(context, widget.video)),\n                      Divider(height: 1, thickness: 1, color: line),\n"), ('재생 화면 ⋮: 잘라서 보내기 · 음악으로 저장 (소리만 듣기 아래)', "                item(Icons.headphones_rounded, '소리만 듣기', 'audioOnly', on: _audioOnly),\n", "                item(Icons.headphones_rounded, '소리만 듣기', 'audioOnly', on: _audioOnly),\n                item(Icons.content_cut_rounded, '잘라서 보내기', 'trim'),\n                item(Icons.music_note_rounded, '음악으로 저장', 'toMusic'),\n"), ('재생 화면 ⋮: 누르면 영상 멈추고 열기', "              if (value == 'rename') {\n", "              if (value == 'trim' || value == 'toMusic') {\n                _videoPlayerController.pause(); // 자르는 동안 멈추기\n                if (value == 'trim') {\n                  await Navigator.push(\n                      context, MaterialPageRoute(builder: (_) => VideoTrimScreen(video: widget.video)));\n                } else {\n                  await showSaveAudioSheet(context, widget.video);\n                }\n                return;\n              }\n              if (value == 'rename') {\n")]
KOTLIN_EDITS = [('앱에서 자르기·소리 저장 요청 받기', '                "trimAndSave" -> {', '                "trimVideo", "extractAudio" -> {\n                    // 동영상 잘라서 저장(영상) / 소리만 뽑아 음악으로 저장 — 다시 압축 안 해서 빠르고 화질 그대로\n                    val path = call.argument<String>("path")\n                    val startMs = (call.argument<Any>("startMs") as? Number)?.toLong() ?: 0L\n                    val endMs = (call.argument<Any>("endMs") as? Number)?.toLong() ?: 0L\n                    val outBase = (call.argument<String>("outBase") ?: "동영상").replace(Regex("[\\\\\\\\/:*?\\"<>|]"), "_")\n                    if (path == null || endMs <= startMs) {\n                        result.success(null)\n                    } else {\n                        val audio = call.method == "extractAudio"\n                        Thread {\n                            val saved = if (audio) saveVideoAudio(path, startMs, endMs, outBase)\n                                        else saveTrimmedVideo(path, startMs, endMs, outBase)\n                            runOnUiThread { result.success(saved) }\n                        }.start()\n                    }\n                }\n                "trimAndSave" -> {'), ('영상 자르기 · 소리 뽑기 · 위치 태그 옮기기', '    private fun getVideoThumbnail(path: String): ByteArray? {', '    /// 동영상 잘라서 Movies/Paransori 에 새로 저장 (원본 그대로). 저장된 경로, 실패면 null\n    private fun saveTrimmedVideo(path: String, startMs: Long, endMs: Long, outBase: String): String? {\n        val tmp = File(cacheDir, "video_trim_tmp.mp4")\n        return try {\n            if (tmp.exists()) tmp.delete()\n            if (!trimVideoWithMuxer(path, tmp, startMs, endMs)) return null\n            saveToMediaStore(tmp, MediaStore.Video.Media.EXTERNAL_CONTENT_URI, "Movies/Paransori", "$outBase.mp4", "video/mp4")\n        } catch (e: Exception) {\n            android.util.Log.e("TrimVideo", "Error: ${e.message}", e)\n            null\n        } finally {\n            tmp.delete()\n        }\n    }\n\n    /// 동영상 소리만 뽑아서 Music/Paransori 에 m4a로 저장. 저장된 경로, 실패면 null\n    private fun saveVideoAudio(path: String, startMs: Long, endMs: Long, outBase: String): String? {\n        val tmp = File(cacheDir, "video_audio_tmp.m4a")\n        return try {\n            if (tmp.exists()) tmp.delete()\n            if (!trimWithMuxer(path, tmp, startMs, endMs)) return null // 노래 자르기와 같은 방식\n            saveToMediaStore(tmp, MediaStore.Audio.Media.EXTERNAL_CONTENT_URI, "Music/Paransori", "$outBase.m4a", "audio/mp4", music = true)\n        } catch (e: Exception) {\n            android.util.Log.e("VideoAudio", "Error: ${e.message}", e)\n            null\n        } finally {\n            tmp.delete()\n        }\n    }\n\n    /// 만든 파일을 폰 갤러리·음악 폴더에 넣기 (같은 이름이 있으면 폰이 (1) 등을 붙임 → 실제 경로 돌려줌)\n    private fun saveToMediaStore(\n        src: File, collection: android.net.Uri, relDir: String, name: String, mime: String, music: Boolean = false\n    ): String? {\n        val values = ContentValues().apply {\n            put(MediaStore.MediaColumns.DISPLAY_NAME, name)\n            put(MediaStore.MediaColumns.MIME_TYPE, mime)\n            put(MediaStore.MediaColumns.RELATIVE_PATH, "$relDir/")\n            if (music) put(MediaStore.Audio.Media.IS_MUSIC, true)\n        }\n        val uri = contentResolver.insert(collection, values) ?: return null\n        contentResolver.openOutputStream(uri)?.use { os -> src.inputStream().use { it.copyTo(os) } }\n        var savedName = name\n        contentResolver.query(uri, arrayOf(MediaStore.MediaColumns.DISPLAY_NAME), null, null, null)?.use { c ->\n            if (c.moveToFirst()) savedName = c.getString(0) ?: savedName\n        }\n        val outPath = File(android.os.Environment.getExternalStorageDirectory(), "$relDir/$savedName").absolutePath\n        android.media.MediaScannerConnection.scanFile(this, arrayOf(outPath), null, null)\n        return outPath\n    }\n\n    /// 영상(화면+소리)을 다시 압축하지 않고 구간만 옮겨 담기 — 시작은 가장 가까운 앞 장면 경계부터\n    private fun trimVideoWithMuxer(src: String, out: File, startMs: Long, endMs: Long): Boolean {\n        val ex = android.media.MediaExtractor()\n        var muxer: android.media.MediaMuxer? = null\n        try {\n            ex.setDataSource(src)\n            val mx = android.media.MediaMuxer(out.absolutePath, android.media.MediaMuxer.OutputFormat.MUXER_OUTPUT_MPEG_4)\n            muxer = mx\n            val dst = HashMap<Int, Int>()\n            var maxSize = 1024 * 1024\n            for (i in 0 until ex.trackCount) {\n                val f = ex.getTrackFormat(i)\n                val mime = f.getString(android.media.MediaFormat.KEY_MIME) ?: continue\n                val isVideo = mime.startsWith("video/")\n                if (!isVideo && !mime.startsWith("audio/")) continue\n                ex.selectTrack(i)\n                dst[i] = mx.addTrack(f)\n                if (f.containsKey(android.media.MediaFormat.KEY_MAX_INPUT_SIZE)) {\n                    maxSize = maxOf(maxSize, f.getInteger(android.media.MediaFormat.KEY_MAX_INPUT_SIZE))\n                }\n                // 세로로 찍은 영상이 눕지 않게 방향 그대로\n                if (isVideo && f.containsKey("rotation-degrees")) mx.setOrientationHint(f.getInteger("rotation-degrees"))\n            }\n            if (dst.isEmpty()) return false\n            // 찍은 곳(위치 태그)도 그대로 옮기기\n            readVideoLocation(src)?.let { (lat, lng) ->\n                try { mx.setLocation(lat, lng) } catch (_: Exception) {}\n            }\n            mx.start()\n            val startUs = startMs * 1000\n            val endUs = endMs * 1000\n            ex.seekTo(startUs, android.media.MediaExtractor.SEEK_TO_PREVIOUS_SYNC)\n            val buf = java.nio.ByteBuffer.allocate(maxSize)\n            val info = android.media.MediaCodec.BufferInfo()\n            val ended = HashSet<Int>()\n            var base = -1L\n            var wrote = false\n            while (true) {\n                val track = ex.sampleTrackIndex\n                if (track < 0) break\n                info.offset = 0\n                info.size = ex.readSampleData(buf, 0)\n                if (info.size < 0) break\n                val t = ex.sampleTime\n                if (t > endUs) {\n                    ended.add(track)\n                    if (ended.size >= dst.size) break\n                    ex.advance()\n                    continue\n                }\n                if (base < 0) base = t\n                if (t < base) {\n                    ex.advance()\n                    continue\n                }\n                info.presentationTimeUs = t - base\n                info.flags = ex.sampleFlags\n                mx.writeSampleData(dst[track]!!, buf, info)\n                wrote = true\n                ex.advance()\n            }\n            if (wrote) mx.stop()\n            return wrote\n        } catch (e: Exception) {\n            android.util.Log.e("TrimVideo", "Error: ${e.message}", e)\n            return false\n        } finally {\n            try { muxer?.release() } catch (_: Exception) {}\n            ex.release()\n        }\n    }\n\n    /// 영상 속 위치 태그 (위도, 경도) — 없으면 null\n    private fun readVideoLocation(path: String): Pair<Float, Float>? {\n        val r = MediaMetadataRetriever()\n        try {\n            var opened = false\n            if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.Q) {\n                try {\n                    contentResolver.query(\n                        MediaStore.Video.Media.EXTERNAL_CONTENT_URI,\n                        arrayOf(MediaStore.Video.Media._ID),\n                        "${MediaStore.Video.Media.DATA}=?", arrayOf(path), null\n                    )?.use {\n                        if (it.moveToFirst()) {\n                            val uri = MediaStore.setRequireOriginal(\n                                android.net.Uri.withAppendedPath(MediaStore.Video.Media.EXTERNAL_CONTENT_URI, it.getLong(0).toString()))\n                            r.setDataSource(this, uri)\n                            opened = true\n                        }\n                    }\n                } catch (_: Exception) {}\n            }\n            if (!opened) r.setDataSource(path)\n            val loc = r.extractMetadata(MediaMetadataRetriever.METADATA_KEY_LOCATION) ?: return null\n            val m = Regex("([+-]\\\\d+(?:\\\\.\\\\d+)?)([+-]\\\\d+(?:\\\\.\\\\d+)?)").find(loc) ?: return null\n            return Pair(m.groupValues[1].toFloat(), m.groupValues[2].toFloat())\n        } catch (_: Exception) {\n            return null\n        } finally {\n            try { r.release() } catch (_: Exception) {}\n        }\n    }\n\n    private fun getVideoThumbnail(path: String): ByteArray? {')]


def balance(t):
    return (t.count('(') - t.count(')'), t.count('[') - t.count(']'), t.count('{') - t.count('}'))


def find_main_activity():
    for root, _, files in os.walk(os.path.join('android', 'app', 'src', 'main')):
        if 'MainActivity.kt' in files:
            return os.path.join(root, 'MainActivity.kt')
    return None


def main():
    ma = find_main_activity()
    if not os.path.exists(SCREEN):
        print('❌ 파일을 못 찾았어요:', SCREEN)
        print('   mp3_player_new 폴더에서 실행했는지 확인해 주세요.')
        sys.exit(1)
    if ma is None:
        print('❌ MainActivity.kt 를 못 찾았어요. mp3_player_new 폴더에서 실행했는지 확인해 주세요.')
        sys.exit(1)

    if DONE_MARK in open(SCREEN, encoding='utf-8').read():
        print('이미 적용돼 있어요. 바꿀 게 없어요.')
        return
    if os.path.exists(NEW_FILE):
        print('❌ video_trim_screen.dart 가 이미 있어요. 아무것도 저장하지 않았어요.')
        sys.exit(1)

    results = {}
    num = 0
    for path, edits in [(ma, KOTLIN_EDITS), (SCREEN, SCREEN_EDITS)]:
        raw = open(path, 'rb').read().decode('utf-8')
        crlf = '\r\n' in raw
        text = raw.replace('\r\n', '\n')
        before = balance(text)
        print(f'[{os.path.basename(path)}]')
        for name, old, new in edits:
            num += 1
            n = text.count(old)
            if n != 1:
                print(f'❌ {num}. {name} — 찾을 곳이 {n}개예요 (1개여야 해요)')
                print('   아무것도 저장하지 않았어요. 지금 파일을 다시 보내주세요.')
                sys.exit(1)
            text = text.replace(old, new)
            print(f'✔ {num}. {name}')
        if balance(text) != before:
            print(f'❌ {os.path.basename(path)} 괄호 개수가 안 맞아요. 아무것도 저장하지 않았어요.')
            sys.exit(1)
        if crlf:
            text = text.replace('\n', '\r\n')
        results[path] = (text, crlf)

    if balance(NEW_DART) != (0, 0, 0):
        print('❌ 새 화면 파일 괄호 개수가 안 맞아요. 아무것도 저장하지 않았어요.')
        sys.exit(1)

    for path, (text, _) in results.items():
        open(path, 'wb').write(text.encode('utf-8'))
    # 새 화면 파일은 video_screen.dart와 같은 줄바꿈으로
    crlf = results[SCREEN][1]
    new_text = NEW_DART.replace('\n', '\r\n') if crlf else NEW_DART
    open(NEW_FILE, 'wb').write(new_text.encode('utf-8'))
    num += 1
    print(f'✔ {num}. 새 화면 만들기: video_trim_screen.dart')
    print(f'완료! {num}군데 바꿨어요.')


main()
